with valid as (select id, account_id, amount, txn_time, is_flagged, round(amount, 0) amount_rounded from transactions where txn_time > date '2023-07-08' and amount <= 1700), scored as (select *, count(amount) over w_running last3_count_amount, avg(amount) over w_running last3_avg_amount, max(amount) over w_running last3_max_amount, min(amount) over w_running last3_min_amount from valid where account_id in (10, 21, 23) window w_running as (partition by account_id order by txn_time asc, id asc rows between 2 preceding and current row)), latest as (select * from scored qualify row_number() over (partition by account_id order by last3_min_amount desc nulls last, id asc) = 1), joined as (select e.id, e.account_id, e.txn_time, e.amount_rounded, e.last3_count_amount, e.last3_max_amount, e.last3_min_amount, a.balance, a.account_type from latest e left join accounts a on e.account_id = a.id), ranked as (select * from (select *, row_number() over (partition by account_type, account_id order by last3_max_amount asc, id asc) as latest_rank from joined) x where latest_rank = 1) select *, lag(last3_min_amount) over (partition by account_type order by latest_rank asc, id asc) prev_last3_min_amount, lag(amount_rounded) over (partition by account_type order by latest_rank asc, id asc) prev_amount_rounded, row_number() over (partition by account_type order by latest_rank asc, id asc) event_seq from ranked
